tool_input.new_string:
/**
 * Units that buy a period rather than a quantity of work.
 *
 * The work is covered by the plan fee, so the honest answer is "included" - not
 * the fee divided by a volume nobody published. Dividing is the mistake
 * `apps/catalog/pricing.py` refuses to make, and this refuses it too.
 */
const SUBSCRIPTION = new Set(['month', 'year', 'seat_month', 'seat_year', 'one_time'])

export function documentCost(plan: PlanOut, input: DocumentInput): DocumentCost {
  const price = plan.prices[0]
  if (!price) return { kind: 'not-comparable' }
  if (SUBSCRIPTION.has(price.unit)) return { kind: 'included' }

  const quantity = QUANTITY[price.unit]
